"""A deliberately simple reference capture parser (materialises everything)."""
import re
TOKEN = re.compile(rb"[!#$%&'*+.^_`|~0-9A-Za-z-]+\Z")
MAX = (1 << 63) - 1

class Syntax(Exception): pass
class Incomplete(Exception): pass

def fp(data):
    h = 0
    for b in data:
        h = (h*257 + b + 1) & ((1 << 64) - 1)
    return {'n': len(data), 'h': '%016x' % h}

def blockfp(fields):
    out = len(fields).to_bytes(8,'big')
    for n,v in fields:
        out += len(n).to_bytes(8,'big') + n + len(v).to_bytes(8,'big') + v
    return fp(out)

def read_line(buf, pos):
    rem = len(buf) - pos
    idx = buf.find(b'\n', pos)
    if idx < 0:
        if rem <= 8193: raise Incomplete()
        raise Syntax()
    if idx - pos > 8193: raise Syntax()
    if idx == pos or buf[idx-1] != 13: raise Syntax()
    return buf[pos:idx-1], idx+1

def parse_field(line):
    i = line.find(b':')
    if i <= 0: raise Syntax()
    name = line[:i]
    if not TOKEN.match(name): raise Syntax()
    val = line[i+1:]
    for b in val:
        if b == 9: continue
        if b < 0x20 or b > 0x7e: raise Syntax()
    return name, val.strip(b' \t')

def parse_all(buf, owner_of):
    """owner_of(start,end) -> (owner, spans)"""
    pos = 0
    out = []
    while pos < len(buf):
        start = pos
        line, pos = read_line(buf, pos)
        bs = len(line)+2
        if bs > 65536: raise Syntax()
        i = line.find(b' ')
        if i <= 0: raise Syntax()
        j = line.find(b' ', i+1)
        if j < 0: raise Syntax()
        method = line[:i]; target = line[i+1:j]; version = line[j+1:]
        if version != b'HTTP/1.1': raise Syntax()
        if not TOKEN.match(method): raise Syntax()
        if not target: raise Syntax()
        for b in target:
            if b < 0x21 or b > 0x7e: raise Syntax()
        fields = []
        while True:
            line, pos = read_line(buf, pos)
            bs += len(line)+2
            if bs > 65536: raise Syntax()
            if not line: break
            if len(fields) >= 128: raise Syntax()
            fields.append(parse_field(line))
        cls = []; tes = []; hostc = 0; hostv = b''
        for n,v in fields:
            ln = n.lower()
            if ln == b'content-length': cls.append(v)
            elif ln == b'transfer-encoding': tes.append(v)
            elif ln == b'host': hostc += 1; hostv = v
        trailers = []
        body = b''
        if tes:
            if len(tes) > 1 or cls: raise Syntax()
            if tes[0].strip(b' \t').lower() != b'chunked': raise Syntax()
            framing = 'chunked'
            while True:
                line, pos = read_line(buf, pos)
                s = line.split(b';')[0]
                if not s or any(not (48<=c<=57 or 97<=c<=102 or 65<=c<=70) for c in s): raise Syntax()
                size = int(s, 16)
                if size > MAX: raise Syntax()
                if line.find(b';') >= 0:
                    for c in line[line.find(b';')+1:]:
                        if c == 9: continue
                        if c < 0x20 or c > 0x7e: raise Syntax()
                if size == 0: break
                if len(buf) - pos < size: raise Incomplete()
                body += buf[pos:pos+size]; pos += size
                if len(buf) - pos < 2: raise Incomplete()
                if buf[pos:pos+2] != b'\r\n': raise Syntax()
                pos += 2
            bs = 0
            while True:
                line, pos = read_line(buf, pos)
                bs += len(line)+2
                if bs > 65536: raise Syntax()
                if not line: break
                if len(trailers) >= 128: raise Syntax()
                n,v = parse_field(line)
                if n.lower() in (b'host', b'content-length', b'transfer-encoding'): raise Syntax()
                trailers.append((n,v))
        elif cls:
            vals = set()
            for v in cls:
                for m in v.split(b','):
                    m = m.strip(b' \t')
                    if not m or not m.isdigit(): raise Syntax()
                    n = int(m)
                    if n > MAX: raise Syntax()
                    vals.add(n)
            if len(vals) != 1: raise Syntax()
            n = vals.pop()
            framing = 'length'
            if len(buf) - pos < n: raise Incomplete()
            body = buf[pos:pos+n]; pos += n
        else:
            framing = 'none'
        end = pos
        owner, spans = owner_of(start, end)
        out.append({'start':start,'end':end,'method':fp(method),'target':fp(target),
                    'host': fp(hostv.lower() if hostc == 1 else b''),
                    'host_count':hostc,'headers':blockfp(fields),'body':fp(body),
                    'trailers':blockfp(trailers),'framing':framing,'owner':owner,
                    'owners':spans})
    return out
PYEOF
